// Chisel, the biome editor (ADR 0074 B3; client/chisel.html): the world's biomes on the left, with
// sliders made from the validation's own ranges (shared/worldgen/biomes.mjs `TERRAIN`), and a live
// top-down preview of a region on the right, generated by the real generator in a worker (coarse
// first, then refined), with the whole world's overview beside it (overview.ts). Edits are kept in the browser; Export / Import move them as JSON.
import {
  GEOLOGY,
  TERRAIN,
  VEGETATION,
  WHERE_FIELDS,
  WORLD_KNOBS,
  type Range,
} from '../../../shared/worldgen/biomes.mjs';
import {
  ARCHIPELAGO_WORLD,
  TALL_PEAK_WORLD,
  BUILD_GEOLOGY,
  BUILD_VEGETATION,
  FULL_BLOCKS,
  PRESETS,
  TEMPLATES,
  addBiome,
  buildEdit,
  fromJson,
  knob,
  loadEdit,
  playInGame,
  saveEdit,
  toJson,
  validateEdit,
  type BiomeJson,
  type Edit,
} from './state';
import { WorldIndex } from '../local/worldIndex';
import { pointAt, rectOn, type Frame } from './overview';
import type { SectionMesh, TileReply, TileRequest } from './worker';
import {
  SECTION_SIZES,
  SectionRenderer,
  sectionCorner,
  sectionFromParams,
  sectionPasses,
  sectionToParams,
  type SectionView,
} from './section';

const store = (() => {
  try {
    return window.localStorage;
  } catch {
    return undefined;
  }
})();
let edit: Edit = loadEdit(store);
let selected = 0;
const view = { seed: 1, cx: 0, cz: 0, size: 2048, overlay: 0, relief: 1 };
/** The 3D section (ADR 0074, the 3D section, 0.52.19): off until asked for, centred on the detail's centre. */
let sec: SectionView = { on: false, x: 0, z: 0, size: 1024 };
/** Where each `where` field's slider runs (the data's range is wider; the number box takes any). */
const WHERE_SPAN: Record<string, [number, number, number]> = {
  temperature: [-0.5, 1.5, 0.01],
  wetness: [0, 1, 0.01],
  elevation: [0, 3000, 10],
  coast: [0, 10000, 50],
};
const BAND_BLOCKS = ['ground', 'under', 'rock', 'shoreBlock'] as const;

/** The edit's soil and vegetation, the build's (a copy) put on the edit the first time it is tuned. */
function vegetation() {
  edit.vegetation ??= JSON.parse(JSON.stringify(BUILD_VEGETATION)) as typeof BUILD_VEGETATION;
  return edit.vegetation;
}

/**
 * The soil and vegetation's sliders (vegetation.json, systemic terrain T3): the °C scale, the soil
 * rules and each kind's key numbers, its least temperature (the tree line) and least moisture.
 */
function vegetationEditor() {
  const v = vegetation();
  const box = el(
    'div',
    {},
    el('p', {
      className: 'about',
      textContent:
        "Only biomes with Vegetation above 0 use these (the boreal, rainforest, savanna, desert and alpine presets); the default biome doesn't.",
    }),
  );
  for (const [group, keys] of Object.entries(VEGETATION)) {
    const obj = v[group as 'climate' | 'soil'];
    for (const [key, [lo, hi]] of Object.entries(keys)) {
      const min = typeof lo === 'object' ? lo.above : lo;
      box.append(
        slider(
          `${group}.${key}`,
          min,
          hi,
          0.1,
          () => Number(obj[key]),
          (x) => (obj[key] = x),
        ),
      );
    }
  }
  for (const k of v.kinds) {
    box.append(el('h2', { textContent: `${k.name} (${k.placement})` }));
    box.append(
      slider(
        'tree line °C',
        -20,
        30,
        0.5,
        () => k.temperature[0],
        (x) => (k.temperature[0] = Math.min(x, k.temperature[1] - 0.5)),
      ),
      slider(
        'least moisture',
        0,
        1,
        0.01,
        () => k.moisture[0],
        (x) => (k.moisture[0] = Math.min(x, k.moisture[1] - 0.01)),
      ),
    );
  }
  return box;
}

/** The edit's geology, the build's (a copy) put on the edit the first time it is shaped. */
/** The geology sliders' tops where the data's range is wider than a slider reads well. */
const GEOLOGY_SLIDER_MAX: Record<string, number> = {
  wavelength: 40_000,
  reach: 3000,
  relief: 20,
  threshold: 200,
  wall: 20,
  talusWidth: 100,
  outlineWavelength: 2000,
  gullyWavelength: 400,
  gullyDepth: 30,
};

function geology() {
  edit.geology ??= JSON.parse(JSON.stringify(BUILD_GEOLOGY)) as typeof BUILD_GEOLOGY;
  // An edit stored before T4 has no erosion: the build's.
  const g = edit.geology;
  g.erosion ??= { ...(BUILD_GEOLOGY.erosion ?? {}) };
  return g as typeof g & { erosion: Record<string, number> };
}

function byId(id: string): HTMLElement {
  const e = document.getElementById(id);
  if (!e) throw new Error(`#${id} is missing`);
  return e;
}

/** An element with `props` assigned and `kids` appended. */
function el(
  tag: string,
  props: Record<string, unknown> = {},
  ...kids: (Node | string)[]
): HTMLElement {
  const e = document.createElement(tag);
  Object.assign(e, props);
  e.append(...kids);
  return e;
}
const input = (props: Record<string, unknown>) => el('input', props) as HTMLInputElement;
const select = () => el('select') as HTMLSelectElement;
const button = (text: string, onclick: () => void, disabled = false) =>
  el('button', { textContent: text, onclick, disabled });

const panel = byId('panel');
const canvas = byId('map') as HTMLCanvasElement;
const status = byId('status');
const errors = el('div', { id: 'errors' });
const ctx = canvas.getContext('2d');

/** A slider and a number box over `get`/`set`, in [min, max] by `step`. */
function slider(
  label: string,
  min: number,
  max: number,
  step: number,
  get: () => number,
  set: (v: number) => void,
) {
  const range = input({
    type: 'range',
    min: String(min),
    max: String(max),
    step: String(step),
    value: String(get()),
  });
  const box = input({ type: 'number', step: String(step), value: String(get()) });
  const apply = (v: number) => {
    if (!Number.isFinite(v)) return;
    set(v);
    range.value = String(v);
    box.value = String(v);
    changed();
  };
  range.oninput = () => {
    apply(Number(range.value));
  };
  box.onchange = () => {
    apply(Number(box.value));
  };
  return el('div', { className: 'row' }, el('span', { textContent: label }), range, box);
}

/** A group's sliders from its `TERRAIN` ranges (the validation's own), around the current value. */
function groupSliders(
  group: string,
  obj: Record<string, unknown>,
  table: Record<string, Record<string, Range>> = TERRAIN,
) {
  const out = el('div');
  const ranges: Record<string, Range> = table[group] ?? {};
  for (const [key, [lo, hi, whole]] of Object.entries(ranges)) {
    const min = typeof lo === 'object' ? lo.above : lo;
    const v = Number(obj[key]);
    // The geology's knobs are 0..1 or a few (strength, tread, sheer) or the provinces' scale.
    const max =
      table === GEOLOGY
        ? Math.min(hi, GEOLOGY_SLIDER_MAX[key] ?? hi)
        : Math.min(hi, Math.max(whole ? 8 : 1, Math.abs(v) * 4));
    const step = whole ? 1 : max <= 2 ? 0.01 : max <= 50 ? 0.1 : 1;
    out.append(
      slider(
        key,
        min,
        max,
        step,
        () => Number(obj[key]),
        (x) => (obj[key] = whole ? Math.round(x) : x),
      ),
    );
  }
  return out;
}

function blockPicker(get: () => string, set: (v: string) => void) {
  const s = select();
  for (const id of FULL_BLOCKS) {
    s.append(
      el('option', { value: id, textContent: id.replace('dwell:', ''), selected: id === get() }),
    );
  }
  s.onchange = () => {
    set(s.value);
    changed();
  };
  return s;
}

/** Rebuilds the panel after a structural change (a range turned on or off, a biome added). */
function restructure() {
  changed();
  render();
}

function whereEditor(where: Record<string, unknown>, isDefault: boolean) {
  const w = el(
    'details',
    { open: true },
    el('summary', { textContent: isDefault ? 'Where (the fallback)' : 'Where' }),
  );
  w.append(
    slider(
      'weight',
      0.01,
      2,
      0.01,
      () => Number(where.weight),
      (v) => (where.weight = v),
    ),
  );
  for (const f of WHERE_FIELDS) {
    const [lo, hi, step] = WHERE_SPAN[f] ?? [0, 1, 0.01];
    const r = where[f] as Record<string, number> | undefined;
    const on = input({ type: 'checkbox', checked: r !== undefined });
    on.onchange = () => {
      if (on.checked) where[f] = { min: lo + (hi - lo) * 0.25, blend: (hi - lo) * 0.05 };
      else Reflect.deleteProperty(where, f);
      restructure();
    };
    w.append(el('label', { className: 'bar' }, on, f));
    if (!r) continue;
    for (const k of ['min', 'max'] as const) {
      const has = input({ type: 'checkbox', checked: r[k] !== undefined, title: `use ${k}` });
      has.onchange = () => {
        if (has.checked) r[k] = lo + (hi - lo) * (k === 'min' ? 0.25 : 0.75);
        else Reflect.deleteProperty(r, k);
        restructure();
      };
      const row =
        r[k] !== undefined
          ? slider(
              k,
              lo,
              hi,
              step,
              () => r[k] ?? 0,
              (v) => (r[k] = v),
            )
          : el('div', { className: 'row' }, el('span', { textContent: k }));
      row.firstElementChild?.prepend(has);
      w.append(row);
    }
    w.append(
      slider(
        'blend',
        0,
        (hi - lo) / 2,
        step,
        () => r.blend ?? 0,
        (v) => (r.blend = v),
      ),
    );
  }
  return w;
}

function biomeEditor(b: BiomeJson, isDefault: boolean) {
  const box = el('div', {}, whereEditor(b.where as Record<string, unknown>, isDefault));
  for (const g of ['detail', 'shaping', 'banks']) {
    box.append(
      el(
        'details',
        {},
        el('summary', { textContent: g }),
        groupSliders(g, b[g] as Record<string, unknown>),
      ),
    );
  }
  box.append(
    slider(
      'vegetation (climate share)',
      0,
      1,
      0.05,
      () => Number(b.vegetation ?? 0),
      (v) => (b.vegetation = v),
    ),
    slider(
      'erosion (cut-back share)',
      0,
      1,
      0.05,
      () => Number(b.erosion ?? 0),
      (v) => (b.erosion = v),
    ),
    slider(
      'gullies (badland rills)',
      0,
      1,
      0.05,
      () => Number(b.gullies ?? 0),
      (v) => (b.gullies = v),
    ),
  );
  box.append(waterEditor(b));
  const bands = el('details', { open: true }, el('summary', { textContent: 'Bands' }));
  b.bands.forEach((band, i) => {
    bands.append(el('h2', { textContent: band.name }));
    if (i > 0) {
      bands.append(
        slider(
          'from (m)',
          0,
          3000,
          10,
          () => band.from ?? 0,
          (v) => (band.from = v),
        ),
      );
    }
    for (const k of BAND_BLOCKS) {
      const pick = blockPicker(
        () => band[k],
        (v) => (band[k] = v),
      );
      bands.append(el('div', { className: 'row' }, el('span', { textContent: k }), pick));
    }
  });
  box.append(bands);
  return box;
}

/** The biome's water hue (`waterLook.scatter`, ADR 0074 B4): a colour picker, or the fluid's own. */
function waterEditor(b: BiomeJson) {
  const look = b.waterLook as { scatter?: string } | undefined;
  const pick = input({ type: 'color', value: look?.scatter ?? '#1496e0' });
  const own = input({ type: 'checkbox', checked: look === undefined });
  pick.oninput = () => {
    b.waterLook = { ...(b.waterLook as object | undefined), scatter: pick.value };
    own.checked = false;
    changed();
  };
  own.onchange = () => {
    if (own.checked) delete b.waterLook;
    else b.waterLook = { scatter: pick.value };
    changed();
  };
  return el(
    'details',
    {},
    el('summary', { textContent: 'water' }),
    el('div', { className: 'row' }, el('span', { textContent: 'hue' }), pick),
    el('div', { className: 'row' }, el('span', { textContent: "fluid's own" }), own),
  );
}

/** The world knobs (the archipelago's; terrain.json's groups): sliders from their ranges. */
function worldEditor() {
  const box = el('div');
  for (const [g, keys] of Object.entries(WORLD_KNOBS)) {
    const vals: Record<string, unknown> = {};
    for (const k of keys) vals[k] = knob(edit, g, k);
    const proxy = new Proxy(vals, {
      set(t, k: string, v: number) {
        t[k] = v;
        edit.world = { ...edit.world, [g]: { ...edit.world?.[g], [k]: v } };
        return true;
      },
    });
    const sl = groupSliders(g, proxy);
    // Only the knobs (`groupSliders` lists every key of the group).
    for (const row of [...sl.children]) {
      if (!keys.includes(row.firstChild?.textContent ?? '')) row.remove();
    }
    box.append(el('h2', { textContent: g }), sl);
  }
  box.append(
    el(
      'div',
      { className: 'bar' },
      button('Archipelago', () => {
        edit = { ...edit, world: structuredClone(ARCHIPELAGO_WORLD) };
        restructure();
      }),
      button('Tall peak', () => {
        edit = { ...edit, world: structuredClone(TALL_PEAK_WORLD) };
        restructure();
      }),
      button('One island', () => {
        delete edit.world;
        restructure();
      }),
    ),
  );
  return box;
}

function download(name: string, text: string) {
  const href = URL.createObjectURL(new Blob([text], { type: 'application/json' }));
  el('a', { href, download: name }).click();
  URL.revokeObjectURL(href);
}

function render() {
  panel.replaceChildren(
    el('h1', { textContent: 'Chisel' }),
    el('div', { className: 'sub', textContent: 'Biomes on the real generator' }),
    el('h2', { textContent: 'Biomes' }),
  );
  const list = el('div', { className: 'bar' });
  edit.biomes.forEach((b, i) => {
    const pick = button(i === 0 ? `${b.name} (default)` : b.name, () => {
      selected = i;
      render();
    });
    if (i === selected) pick.className = 'on';
    list.append(pick);
  });
  const tpl = select();
  for (const t of TEMPLATES) tpl.append(el('option', { value: t.name, textContent: t.name }));
  // The presets (Add preset): by label, the description as the option's tooltip and below.
  const presetPick = select();
  for (const p of PRESETS) {
    presetPick.append(el('option', { value: p.name, textContent: p.label, title: p.description }));
  }
  const presetAbout = el('p', { className: 'about', textContent: PRESETS[0]?.description ?? '' });
  presetPick.addEventListener('change', () => {
    presetAbout.textContent = PRESETS.find((p) => p.name === presetPick.value)?.description ?? '';
  });
  const add = (from: BiomeJson | undefined) => {
    if (!from) return;
    edit = addBiome(edit, from);
    selected = edit.biomes.length - 1;
    restructure();
  };
  const actions = el(
    'div',
    { className: 'bar' },
    tpl,
    button('Add', () => {
      add(TEMPLATES.find((t) => t.name === tpl.value));
    }),
    button('Duplicate', () => {
      add(edit.biomes[selected]);
    }),
    button(
      'Remove',
      () => {
        edit = { ...edit, biomes: edit.biomes.filter((_, i) => i !== selected) };
        selected = 0;
        restructure();
      },
      selected === 0,
    ),
  );
  const presets = el(
    'div',
    { className: 'bar' },
    presetPick,
    button('Add from preset', () => {
      add(PRESETS.find((t) => t.name === presetPick.value));
    }),
  );
  panel.append(list, actions, presets, presetAbout, errors);
  const b = edit.biomes[selected];
  if (b) panel.append(el('h2', { textContent: b.name }), biomeEditor(b, selected === 0));
  panel.append(
    el(
      'details',
      {},
      el('summary', { textContent: 'Biome map (terrain.json)' }),
      groupSliders('biomeMap', edit.biomeMap),
    ),
    el(
      'details',
      { open: edit.world !== undefined },
      el('summary', { textContent: 'World: coast and islands (terrain.json)' }),
      worldEditor(),
    ),
    el(
      'details',
      {},
      el('summary', { textContent: 'Rock: provinces and shaping (rocks.json)' }),
      el('p', {
        className: 'about',
        textContent:
          'Strength 0 leaves the ground as generated; a biome with a rockStack (the mesa and badlands presets) takes its own stack.',
      }),
      groupSliders('shaping', geology().shaping, GEOLOGY),
      groupSliders('provinces', geology().provinces, GEOLOGY),
    ),
    el(
      'details',
      {},
      el('summary', { textContent: 'Erosion: cut-back (rocks.json erosion)' }),
      el('p', {
        className: 'about',
        textContent:
          'Scarps retreat from the drainage lines; nearer than the retreat the land is the floor, farther it stands as mesas and buttes. A biome opts in with its erosion slider (the mesa and badlands presets at 1).',
      }),
      groupSliders('erosion', geology().erosion, GEOLOGY),
    ),
    el(
      'details',
      {},
      el('summary', { textContent: 'Soil and vegetation (vegetation.json)' }),
      vegetationEditor(),
    ),
  );
  const file = input({ type: 'file', accept: 'application/json' });
  file.onchange = async () => {
    const f = file.files?.[0];
    if (!f) return;
    const r = fromJson(await f.text(), edit);
    if ('errors' in r) {
      errors.textContent = r.errors.join('\n');
      return;
    }
    edit = r.edit;
    selected = 0;
    restructure();
  };
  panel.append(
    el('h2', { textContent: 'File' }),
    el(
      'div',
      { className: 'bar' },
      button('Export', () => {
        download('chisel-biomes.json', toJson(edit));
      }),
      button('Import', () => {
        file.click();
      }),
      button('Reset', () => {
        edit = buildEdit();
        selected = 0;
        saveEdit(store, null);
        restructure();
      }),
      // A new local world on this edit's ground (docs/DEV_TOOLS.md "Play a test world"): its
      // record keeps the edit, so it reopens the same. The world knobs only, not the biomes yet.
      el('button', {
        textContent: 'Play in game',
        title:
          'Opens a new local world on this edit (the seed above): its biomes, rocks, erosion, vegetation and world knobs',
        onclick: () => {
          if (validateEdit(edit).length) return;
          const id = playInGame(new WorldIndex(store ?? null), edit, view.seed, Date.now());
          window.open(`./?play=${encodeURIComponent(id)}`, '_blank');
        },
      }),
    ),
  );
}

// --- the preview ---------------------------------------------------------------------------------

const worker = new Worker(new URL('./worker.ts', import.meta.url), { type: 'module' });
let next = 1;
let wanted = 0;
let timer = 0;
/** The passes of each regeneration, texels a side: coarse first, then refined. */
const PASSES = [64, 256];

function changed() {
  const errs = validateEdit(edit);
  errors.textContent = errs.join('\n');
  if (errs.length) return;
  saveEdit(store, edit);
  clearTimeout(timer);
  timer = window.setTimeout(() => {
    regenerate();
  }, 60);
}

/** Asks for the detail preview, and (unless only the view moved) the overview after it. */
function regenerate(overview = true) {
  wanted = next;
  const gen = next;
  const text = JSON.stringify(edit);
  for (const n of PASSES) {
    const texel = Math.max(1, Math.round(view.size / n));
    const req: TileRequest = {
      id: next++,
      lane: 'detail',
      gen,
      seed: view.seed,
      edit: text,
      x0: Math.round(view.cx - (n * texel) / 2),
      z0: Math.round(view.cz - (n * texel) / 2),
      n,
      texel,
      overlay: view.overlay,
      relief: view.relief === 1,
    };
    worker.postMessage(req);
  }
  drawOverview();
  requestSection();
  if (!overview) return;
  ov.wanted = next;
  ov.pass = 0;
  ov.passMs.clear();
  const req: TileRequest = {
    id: next++,
    lane: 'overview',
    gen: ov.wanted,
    seed: view.seed,
    edit: text,
    x0: 0,
    z0: 0,
    n: 0,
    texel: 0,
    overlay: view.overlay,
    relief: view.relief === 1,
  };
  worker.postMessage(req);
}

// The 3D section: its passes (coarse, then fine) in the worker's 'section' lane after the detail;
// a newer request drops the older passes; the newest mesh drawn.
const secCanvas = byId('section') as HTMLCanvasElement;
const secBox = byId('section-box');
const secStatus = byId('section-status');
let secRenderer: SectionRenderer | null = null;
let secWanted = 0;
/** The square the mesh on screen shows (a new square reframes the camera). */
let secShown = '';
const secMs: string[] = [];

function requestSection() {
  secBox.hidden = !sec.on;
  const p = new URLSearchParams(location.search);
  sectionToParams(sec, p);
  p.set('relief', String(view.relief));
  history.replaceState(null, '', `${location.pathname}?${p.toString()}`);
  drawSectionSquare();
  if (!sec.on) return;
  secWanted = next;
  secMs.length = 0;
  const { x0, z0 } = sectionCorner(sec);
  const text = JSON.stringify(edit);
  for (const { n, texel } of sectionPasses(sec.size)) {
    const req: TileRequest = {
      id: next++,
      lane: 'section',
      gen: secWanted,
      seed: view.seed,
      edit: text,
      x0,
      z0,
      n,
      texel,
      overlay: 0,
      relief: false,
    };
    worker.postMessage(req);
  }
}

async function sectionReply(m: SectionMesh, ms: number) {
  if (!secRenderer) {
    secRenderer = await SectionRenderer.create(secCanvas);
    if (!secRenderer) {
      secStatus.textContent = 'The 3D view needs WebGPU.';
      return;
    }
    secRenderer.attach();
  }
  const key = `${String(view.seed)}|${String(m.x0)},${String(m.z0)}|${String(m.n * m.texel)}`;
  const t0 = performance.now();
  secRenderer.setMesh(m, key !== secShown);
  secShown = key;
  const draw = performance.now() - t0;
  const tris = (m.groundIndex.length + m.waterIndex.length) / 3;
  secMs.push(
    `${String(m.texel)} m: ${String(Math.round(ms))} ms + ${String(Math.round(draw))} ms draw`,
  );
  secStatus.textContent = `${String(m.n * m.texel)} m at (${String(sec.x)}, ${String(sec.z)}) · ${secMs.join(', ')} · ${String(Math.round(tris / 1000))}k triangles${secRenderer.exag > 1 ? ` · heights ×${String(secRenderer.exag)}` : ''} · drag orbits, shift-drag pans, wheel zooms; click the detail to move it`;
  document.body.dataset.section = `${String(m.texel)}:${String(Math.round(ms))}:${String(Math.round(draw))}`;
}

/** The section's square on the detail preview (and the overview's rectangle is the detail's). */
function drawSectionSquare() {
  if (!ctx || !sec.on || !lastDetail) return;
  ctx.imageSmoothingEnabled = false;
  ctx.drawImage(lastDetail, 0, 0, canvas.width, canvas.height);
  const k = canvas.width / view.size;
  const x = (sec.x - sec.size / 2 - (view.cx - view.size / 2)) * k;
  const y = (sec.z - sec.size / 2 - (view.cz - view.size / 2)) * k;
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 3;
  ctx.strokeRect(x, y, sec.size * k, sec.size * k);
  ctx.strokeStyle = '#ffe680';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(x, y, sec.size * k, sec.size * k);
}
let lastDetail: OffscreenCanvas | null = null;

canvas.onclick = (ev) => {
  if (!sec.on) return;
  const b = canvas.getBoundingClientRect();
  sec = {
    ...sec,
    x: Math.round(view.cx - view.size / 2 + ((ev.clientX - b.left) / b.width) * view.size),
    z: Math.round(view.cz - view.size / 2 + ((ev.clientY - b.top) / b.height) * view.size),
  };
  requestSection();
};

// The overview: the world disc, its passes drawn into `ov.image` chunk by chunk (a finer pass over
// the coarse one), the detail region's rectangle over it; a click or drag moves the detail's centre.
const ovCanvas = byId('overview') as HTMLCanvasElement;
const ovCtx = ovCanvas.getContext('2d');
const ovStatus = byId('overview-status');
const ov = {
  wanted: 0,
  frame: null as Frame | null,
  image: new OffscreenCanvas(512, 512),
  pass: 0,
  passMs: new Map<number, number>(),
};

function drawOverview() {
  if (!ovCtx) return;
  ovCtx.imageSmoothingEnabled = false;
  ovCtx.clearRect(0, 0, ovCanvas.width, ovCanvas.height);
  ovCtx.drawImage(ov.image, 0, 0, ovCanvas.width, ovCanvas.height);
  if (!ov.frame) return;
  const r = rectOn(ov.frame, view.cx, view.cz, view.size);
  const s = ovCanvas.width;
  // At least a few pixels, so a 1 km region still shows on the 100 km disc.
  const w = Math.max(6, r.w * s);
  const [x, y] = [r.u * s + (r.w * s - w) / 2, r.v * s + (r.w * s - w) / 2];
  ovCtx.strokeStyle = '#000';
  ovCtx.lineWidth = 4;
  ovCtx.strokeRect(x, y, w, w);
  ovCtx.strokeStyle = '#fff';
  ovCtx.lineWidth = 2;
  ovCtx.strokeRect(x, y, w, w);
}

function overviewReply(r: Extract<TileReply, { rgba: Uint8ClampedArray }>) {
  if (r.gen < ov.wanted || !r.frame || r.pass === undefined) return;
  const g = ov.image.getContext('2d');
  if (!g) return;
  // A coarse chunk never covers the finer pass already drawn.
  if (r.pass < ov.pass) return;
  ov.pass = r.pass;
  ov.frame = r.frame;
  const scale = ov.image.width / r.frame.n;
  const off = new OffscreenCanvas(r.n, r.n);
  off.getContext('2d')?.putImageData(new ImageData(new Uint8ClampedArray(r.rgba), r.n, r.n), 0, 0);
  g.imageSmoothingEnabled = false;
  const [x, y, w] = [(r.i ?? 0) * scale, (r.j ?? 0) * scale, r.n * scale];
  g.clearRect(x, y, w, w);
  g.drawImage(off, x, y, w, w);
  ov.passMs.set(r.pass, (ov.passMs.get(r.pass) ?? 0) + r.ms);
  drawOverview();
  const km = (r.frame.texel / 1000).toFixed(2);
  const parts = [...ov.passMs].map(([n, ms]) => `${String(n)}² in ${String(Math.round(ms))} ms`);
  ovStatus.textContent = `The disc, ${String((r.frame.n * r.frame.texel) / 1000)} km across · ${km} km texels · ${parts.join(', ')}${r.cached ? ' (cached)' : ''} · click or drag to move the preview`;
  if (r.last) {
    document.body.dataset.overview = `${String(r.pass)}:${String(Math.round(ov.passMs.get(r.pass) ?? 0))}`;
  }
}

/** The view bar's number boxes, refreshed from `view` when the overview moves the centre. */
const viewInputs: Partial<Record<'cx' | 'cz', () => void>> = {};

let dragging = false;
function moveTo(ev: PointerEvent) {
  if (!ov.frame) return;
  const b = ovCanvas.getBoundingClientRect();
  const p = pointAt(ov.frame, (ev.clientX - b.left) / b.width, (ev.clientY - b.top) / b.height);
  view.cx = p.x;
  view.cz = p.z;
  viewInputs.cx?.();
  viewInputs.cz?.();
  drawOverview();
  clearTimeout(timer);
  timer = window.setTimeout(() => {
    regenerate(false);
  }, 30);
}
ovCanvas.onpointerdown = (ev) => {
  dragging = true;
  ovCanvas.setPointerCapture(ev.pointerId);
  moveTo(ev);
};
ovCanvas.onpointermove = (ev) => {
  if (dragging) moveTo(ev);
};
ovCanvas.onpointerup = () => {
  dragging = false;
};

worker.onmessage = (ev: MessageEvent<TileReply>) => {
  const r = ev.data;
  if (r.lane === 'section') {
    if (r.gen < secWanted) return;
    if ('error' in r) secStatus.textContent = r.error;
    else if ('mesh' in r) void sectionReply(r.mesh, r.ms);
    return;
  }
  if ('mesh' in r) return;
  if (r.lane === 'overview') {
    if ('error' in r) ovStatus.textContent = r.error;
    else overviewReply(r);
    return;
  }
  if (r.id < wanted || !ctx) return;
  if ('error' in r) {
    status.textContent = r.error;
    return;
  }
  const off = new OffscreenCanvas(r.n, r.n);
  off.getContext('2d')?.putImageData(new ImageData(new Uint8ClampedArray(r.rgba), r.n, r.n), 0, 0);
  ctx.imageSmoothingEnabled = false;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.drawImage(off, 0, 0, canvas.width, canvas.height);
  lastDetail = off;
  drawSectionSquare();
  const texel = Math.round(view.size / r.n);
  status.textContent = `${String(r.n)}² texels of ${String(texel)} m in ${String(Math.round(r.ms))} ms · seed ${String(view.seed)}`;
  document.body.dataset.tiles = String(Number(document.body.dataset.tiles ?? 0) + 1);
};

function viewBar() {
  const bar = byId('view');
  const num = (label: string, key: 'seed' | 'cx' | 'cz') => {
    const i = input({ type: 'number', value: String(view[key]), className: 'num' });
    i.onchange = () => {
      view[key] = Number(i.value) || 0;
      regenerate(key === 'seed');
    };
    if (key !== 'seed') {
      viewInputs[key] = () => {
        i.value = String(view[key]);
      };
    }
    return el('label', {}, `${label} `, i);
  };
  const size = select();
  for (const s of [1024, 2048, 4096, 16384]) {
    size.append(
      el('option', {
        value: String(s),
        textContent: `${String(s / 1000)} km`,
        selected: s === view.size,
      }),
    );
  }
  size.onchange = () => {
    view.size = Number(size.value);
    regenerate(false);
  };
  const overlay = select();
  [
    'blocks',
    'biome weights',
    'temperature',
    'wetness',
    'rainfall',
    'rock',
    'soil',
    'vegetation',
    'erosion',
    'tectonics',
  ].forEach((t, i) => {
    overlay.append(
      el('option', { value: String(i), textContent: t, selected: i === view.overlay }),
    );
  });
  overlay.onchange = () => {
    view.overlay = Number(overlay.value);
    regenerate();
  };
  const relief = el('button', {
    textContent: 'relief',
    className: view.relief ? 'on' : '',
    title: 'Hill-shade the 2D views (sun from the north-west)',
  });
  relief.onclick = () => {
    view.relief = view.relief ? 0 : 1;
    relief.className = view.relief ? 'on' : '';
    regenerate();
  };
  const three = el('button', {
    textContent: '3D',
    className: sec.on ? 'on' : '',
    title: 'A 3D view of a square of the world; click the detail to move it',
  });
  const secSize = select();
  for (const s of SECTION_SIZES) {
    secSize.append(
      el('option', { value: String(s), textContent: `${String(s)} m`, selected: s === sec.size }),
    );
  }
  three.onclick = () => {
    sec = sec.on ? { ...sec, on: false } : { ...sec, on: true, x: view.cx, z: view.cz };
    three.className = sec.on ? 'on' : '';
    requestSection();
  };
  secSize.onchange = () => {
    sec = { ...sec, size: Number(secSize.value) };
    requestSection();
  };
  bar.append(
    num('seed', 'seed'),
    num('x', 'cx'),
    num('z', 'cz'),
    size,
    overlay,
    relief,
    three,
    secSize,
  );
}

const params = new URLSearchParams(location.search);
for (const k of ['seed', 'cx', 'cz', 'size', 'overlay', 'relief'] as const) {
  const v = params.get(k);
  if (v !== null && Number.isFinite(Number(v))) view[k] = Number(v);
}
sec = sectionFromParams(params, { ...sec, x: view.cx, z: view.cz });
viewBar();
render();
errors.textContent = validateEdit(edit).join('\n');
regenerate();
